final class SN_Future24_Review_Hardening_G {
    public static function register():void{add_action('rest_api_init',[self::class,'routes'],1997);add_action('sn_network_event_queued',[self::class,'semantic_index_event'],30,2);add_action('sn_cleanup_hourly',[self::class,'retry_semantic_purges'],35);}
    public static function routes():void{
        register_rest_route('sabri-network/v2','/calls/(?P<id>\d+)/network-quality',['methods'=>'POST','callback'=>[self::class,'network_quality'],'permission_callback'=>[SN_REST::class,'access']],true);
        register_rest_route('sabri-network/v2','/future/ai-assistant',['methods'=>'POST','callback'=>[self::class,'ai_assistant'],'permission_callback'=>[SN_REST::class,'access']],true);
        register_rest_route('sabri-network/v2','/future/semantic-search',['methods'=>'POST','callback'=>[self::class,'semantic_search'],'permission_callback'=>[SN_REST::class,'access']],true);
        register_rest_route('sabri-network/v2','/future/semantic-search/consent',['methods'=>'POST','callback'=>[self::class,'semantic_consent'],'permission_callback'=>[SN_REST::class,'access']]);
    }
    public static function network_quality(WP_REST_Request $r):WP_REST_Response|WP_Error{global $wpdb;$call=absint($r['id']);$user=get_current_user_id();if(!self::call_member($call,$user))return self::not_found();$loss=max(0,min(100,(float)$r->get_param('packet_loss_pct')));$rtt=max(0,min(5000,absint($r->get_param('rtt_ms'))));$jitter=max(0,min(5000,absint($r->get_param('jitter_ms'))));$down=max(0,min(1000000,absint($r->get_param('downlink_kbps'))));$quality=$loss>=8||$rtt>=700?'poor':($loss>=3||$rtt>=350?'fair':'good');$hints=$quality==='poor'?['prefer_audio_only'=>true,'reduce_video_resolution'=>true,'retry_ice'=>true]:($quality==='fair'?['reduce_video_resolution'=>true]:[]);$consent=rest_sanitize_boolean($r->get_param('telemetry_consent'));if(!$consent)return rest_ensure_response(['quality'=>$quality,'hints'=>$hints,'stored'=>false,'diagnostic_only'=>true]);$expires=gmdate('Y-m-d H:i:s',time()+max(1,min(72,(int)apply_filters('sn_network_quality_retention_hours',24,$user,$call)))*HOUR_IN_SECONDS);$payload=['quality'=>$quality,'packet_loss_bucket'=>self::bucket($loss,[1,3,8,15]),'rtt_bucket'=>self::bucket($rtt,[100,250,500,1000]),'jitter_bucket'=>self::bucket($jitter,[20,50,100,250]),'downlink_bucket'=>self::bucket($down,[300,1000,3000,10000]),'consent'=>true];$id=self::upsert_quality($user,$call,$payload,$expires);if(is_wp_error($id))return $id;SN_DB::audit('future_network_quality','call',$call,'success',['quality'=>$quality,'retention_hours'=>round((strtotime($expires)-time())/HOUR_IN_SECONDS)],$user);return rest_ensure_response(['quality'=>$quality,'hints'=>$hints,'stored'=>true,'expires_at'=>$expires,'diagnostic_only'=>true]);}
    public static function ai_assistant(WP_REST_Request $r):WP_REST_Response|WP_Error{global $wpdb;$user=get_current_user_id();$conversation=absint($r->get_param('conversation_id'));if($conversation<=0||!SN_DB::is_member($conversation,$user))return self::not_found();if(!rest_sanitize_boolean($r->get_param('explicit_consent')))return self::error('sn_ai_consent_required','Explicit per-request consent is required.',400);$task=sanitize_key((string)$r->get_param('task'));if(!in_array($task,['summary','draft','action_items','explain'],true))return self::error('sn_ai_task_invalid','Select an approved AI assistance task.',400);if(!has_filter('sn_network_ai_context_authorized')||!(bool)apply_filters('sn_network_ai_context_authorized',false,$user,$conversation,$task))return self::error('sn_ai_governance_unavailable','File 16 AI governance has not authorized this exact task and context.',503);if(SN_Policy::age_state($user)!=='adult'&&!(bool)apply_filters('sn_network_ai_minor_allowed',false,$user,$conversation,$task))return self::error('sn_ai_minor_restricted','AI assistance is unavailable in this minor-account context.',403);if(!has_filter('sn_network_ai_context_redact'))return self::error('sn_ai_redaction_unavailable','Approved privacy redaction is required before private context leaves File 17.',503);$ids=array_slice(array_values(array_unique(array_filter(array_map('absint',(array)$r->get_param('message_ids'))))),0,50);if(!$ids)return self::error('sn_selected_messages_required','Select one or more messages.',400);$messages=[];foreach($ids as $id){$m=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.SN_DB::table('messages').' WHERE id=%d',$id));if(!$m||(int)$m->conversation_id!==$conversation||!empty($m->deleted_at)||SN_Message_Operations::is_hidden($user,$id))return self::not_found();$plain=SN_Message_Body::decrypt_row($m);if(is_wp_error($plain))return $plain;$redacted=apply_filters('sn_network_ai_context_redact',null,(string)$plain,$id,$conversation,$user,$task);$plain='';if(!is_string($redacted))return self::error('sn_ai_redaction_failed','Selected context did not pass privacy redaction.',400);$messages[]=['message_id'=>$id,'sender_id'=>(int)$m->sender_id,'body'=>mb_substr($redacted,0,8000),'created_at'=>(string)$m->created_at];}if(!SN_DB::is_member($conversation,$user)||!rest_sanitize_boolean($r->get_param('explicit_consent'))||(bool)apply_filters('sn_network_ai_context_authorized',false,$user,$conversation,$task)!==true){self::wipe_messages($messages);return self::error('sn_ai_context_stale','Conversation or AI authorization changed before handoff.',409);}foreach($ids as $id){$m=$wpdb->get_row($wpdb->prepare('SELECT id,conversation_id,deleted_at FROM '.SN_DB::table('messages').' WHERE id=%d',$id));if(!$m||(int)$m->conversation_id!==$conversation||!empty($m->deleted_at)||SN_Message_Operations::is_hidden($user,$id)){self::wipe_messages($messages);return self::not_found();}}$payload=['task'=>$task,'messages'=>$messages,'conversation_id'=>$conversation,'user_id'=>$user,'clinical_authority'=>false,'diagnosis_prescription_authority'=>false,'store_context'=>false];$result=apply_filters('sn_network_ai_assistant_result',null,$payload);self::wipe_messages($messages);unset($payload);if($result===null)return self::error('sn_ai_provider_unavailable','AI assistance requires the approved File 16 adapter.',503);if(is_wp_error($result))return $result;SN_DB::audit('future_ai_assistant','conversation',$conversation,'success',['task'=>$task,'selected_count'=>count($ids),'context_stored'=>false],$user);return rest_ensure_response(['task'=>$task,'result'=>$result,'stored_by_file17'=>false,'clinical_authority'=>false]);}
    public static function semantic_consent(WP_REST_Request $r):WP_REST_Response|WP_Error{
        $user=get_current_user_id();$enabled=rest_sanitize_boolean($r->get_param('enabled'));$saved=self::save_semantic_consent($user,$enabled,!$enabled);if(is_wp_error($saved))return $saved;do_action('sn_network_private_semantic_consent_changed',$user,$enabled);
        $purge_complete=true;if(!$enabled){$purge=has_filter('sn_network_private_semantic_purge_result')?apply_filters('sn_network_private_semantic_purge_result',null,$user,['reason'=>'consent_withdrawn','owner'=>'file-17']):null;$purge_complete=self::purge_confirmed($purge);if($purge_complete)self::clear_semantic_purge_pending($user);else SN_DB::audit('future_semantic_purge_pending','user',$user,'failure',['reason'=>'provider_unavailable_or_unconfirmed'],0);}
        SN_DB::audit('future_semantic_consent','user',$user,'success',['enabled'=>$enabled,'purge_complete'=>$purge_complete],$user);return rest_ensure_response(['enabled'=>$enabled,'owner'=>'file-17','global_search_owner'=>'file-26','private_corpus_exported'=>false,'purge_pending'=>!$enabled&&!$purge_complete]);
    }
    public static function semantic_search(WP_REST_Request $r):WP_REST_Response|WP_Error{
        global $wpdb;$user=get_current_user_id();$conversation=absint($r->get_param('conversation_id'));if($conversation<=0||!SN_DB::is_member($conversation,$user))return self::not_found();if(!self::semantic_consent_enabled($user))return self::error('sn_semantic_opt_in_required','Enable private semantic search before using it.',403);$query=mb_substr(sanitize_text_field((string)$r->get_param('query')),0,500);if(mb_strlen($query)<2)return self::error('sn_semantic_query_invalid','Enter a longer search query.',400);if(!has_filter('sn_network_private_semantic_search_result'))return self::error('sn_semantic_provider_unavailable','Private semantic search requires an approved File-17 private-search adapter.',503);
        if(!SN_DB::is_member($conversation,$user)||!self::semantic_consent_enabled($user))return self::error('sn_semantic_context_stale','Semantic-search consent or conversation access changed before provider handoff.',409);
        $result=apply_filters('sn_network_private_semantic_search_result',null,$query,$conversation,$user,['owner'=>'file-17','consent'=>true,'file26_export'=>false]);$query='';if($result===null)return self::error('sn_semantic_provider_unavailable','Private semantic search requires an approved File-17 private-search adapter.',503);if(is_wp_error($result))return $result;if(!SN_DB::is_member($conversation,$user)||!self::semantic_consent_enabled($user))return self::error('sn_semantic_context_stale','Semantic-search consent or conversation access changed before results could be exposed.',409);
        $ids=array_slice(array_values(array_unique(array_filter(array_map('absint',(array)($result['message_ids']??$result))))),0,50);$items=[];foreach($ids as $id){$m=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.SN_DB::table('messages').' WHERE id=%d',$id));if(!$m||(int)$m->conversation_id!==$conversation||!empty($m->deleted_at)||SN_Message_Operations::is_hidden($user,$id))continue;$plain=SN_Message_Body::decrypt_row($m);if(is_wp_error($plain))continue;$items[]=['message_id'=>$id,'snippet'=>mb_substr((string)$plain,0,500),'created_at'=>(string)$m->created_at];$plain='';}SN_DB::audit('future_semantic_search','conversation',$conversation,'success',['result_count'=>count($items),'query_logged'=>false],$user);return rest_ensure_response(['items'=>$items,'owner'=>'file-17','exported_to_file26'=>false,'authoritative_visibility_rechecked'=>true]);
    }
    public static function semantic_index_event($event,string $type):void{
        if(!in_array($type,['message.sent','message.created','message.updated','message.deleted','message.expired','message.forwarded'],true))return;
        // The event source is intentionally opaque here. A registered owner-side gate must
        // resolve it to consenting, currently authorized projections; no gate means no index signal.
        if(!has_filter('sn_network_private_semantic_index_event_allowed')||!(bool)apply_filters('sn_network_private_semantic_index_event_allowed',false,$event,$type,['owner'=>'file-17','require_current_consent'=>true]))return;
        $event_id=is_numeric($event)?(int)$event:0;do_action('sn_network_private_semantic_index_change',['event_type'=>$type,'event_id'=>$event_id,'owner'=>'file-17','include_plaintext'=>false,'consent_gate_passed'=>true,'file26_export'=>false]);
    }
    public static function retry_semantic_purges():void{global $wpdb;$rows=$wpdb->get_results("SELECT * FROM ".$wpdb->prefix."sn_future_records WHERE feature_id='F17-FUT-23' AND scope_type='user' AND state='active' ORDER BY id ASC LIMIT 100");foreach(is_array($rows)?$rows:[] as $row){$d=self::decode($row);if(is_wp_error($d)||!empty($d['enabled'])||empty($d['purge_pending']))continue;$user=(int)$row->owner_id;$purge=has_filter('sn_network_private_semantic_purge_result')?apply_filters('sn_network_private_semantic_purge_result',null,$user,['reason'=>'consent_withdrawn_retry','owner'=>'file-17']):null;if(self::purge_confirmed($purge))self::clear_semantic_purge_pending($user);}}
    private static function purge_confirmed($result):bool{if($result===true)return true;if(!is_array($result)||($result['confirmed']??false)!==true)return false;$state=sanitize_key((string)($result['state']??''));return in_array($state,['purged','deleted','removed'],true);}
    private static function save_semantic_consent(int $user,bool $enabled,bool $purge_pending=false):int|WP_Error{global $wpdb;$key=hash('sha256','semantic-consent:'.$user);$row=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.$wpdb->prefix.'sn_future_records WHERE client_key=%s LIMIT 1',$key));$dummy=$row?:((object)['feature_id'=>'F17-FUT-23','owner_id'=>$user,'scope_type'=>'user','scope_id'=>$user,'version'=>0]);$cipher=self::encode($dummy,['subtype'=>'consent','enabled'=>$enabled,'purge_pending'=>$purge_pending,'updated_at'=>current_time('mysql',true)]);if(is_wp_error($cipher))return $cipher;$now=current_time('mysql',true);if($row){$ok=$wpdb->update($wpdb->prefix.'sn_future_records',['payload_cipher'=>$cipher,'state'=>'active','updated_at'=>$now,'version'=>(int)$row->version+1],['id'=>(int)$row->id,'version'=>(int)$row->version]);return $ok===1?(int)$row->id:self::error('sn_semantic_consent_conflict','Semantic-search consent changed concurrently.',409);}$ok=$wpdb->insert($wpdb->prefix.'sn_future_records',['feature_id'=>'F17-FUT-23','owner_id'=>$user,'scope_type'=>'user','scope_id'=>$user,'state'=>'active','payload_cipher'=>$cipher,'client_key'=>$key,'created_at'=>$now,'updated_at'=>$now,'version'=>1]);return $ok===false?self::error('database_error','Semantic-search consent could not be stored safely.',500):(int)$wpdb->insert_id;}
    private static function clear_semantic_purge_pending(int $user):void{global $wpdb;$key=hash('sha256','semantic-consent:'.$user);$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM ".$wpdb->prefix."sn_future_records WHERE client_key=%s AND feature_id='F17-FUT-23' AND state='active' LIMIT 1",$key));if(!$row)return;$d=self::decode($row);if(is_wp_error($d)||!empty($d['enabled'])||empty($d['purge_pending']))return;$d['purge_pending']=false;$d['purged_at']=current_time('mysql',true);$cipher=self::encode($row,$d);if(is_wp_error($cipher))return;$wpdb->update($wpdb->prefix.'sn_future_records',['payload_cipher'=>$cipher,'updated_at'=>current_time('mysql',true),'version'=>(int)$row->version+1],['id'=>(int)$row->id,'version'=>(int)$row->version]);}
    private static function semantic_consent_enabled(int $user):bool{global $wpdb;$key=hash('sha256','semantic-consent:'.$user);$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM ".$wpdb->prefix."sn_future_records WHERE client_key=%s AND state='active' LIMIT 1",$key));if(!$row)return false;$d=self::decode($row);return !is_wp_error($d)&&!empty($d['enabled']);}
    private static function upsert_quality(int $owner,int $call,array $data,string $expires):int|WP_Error{global $wpdb;$key=hash('sha256','quality:'.$call.':'.$owner);$row=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.$wpdb->prefix.'sn_future_records WHERE client_key=%s LIMIT 1',$key));$dummy=$row?:((object)['feature_id'=>'F17-FUT-21','owner_id'=>$owner,'scope_type'=>'call','scope_id'=>$call,'version'=>0]);$cipher=self::encode($dummy,$data);if(is_wp_error($cipher))return $cipher;$now=current_time('mysql',true);if($row){$ok=$wpdb->update($wpdb->prefix.'sn_future_records',['payload_cipher'=>$cipher,'state'=>'active','expires_at'=>$expires,'updated_at'=>$now,'version'=>(int)$row->version+1],['id'=>(int)$row->id,'version'=>(int)$row->version]);return $ok===1?(int)$row->id:self::error('sn_quality_conflict','Quality state changed concurrently.',409);}$ok=$wpdb->insert($wpdb->prefix.'sn_future_records',['feature_id'=>'F17-FUT-21','owner_id'=>$owner,'scope_type'=>'call','scope_id'=>$call,'state'=>'active','payload_cipher'=>$cipher,'client_key'=>$key,'expires_at'=>$expires,'created_at'=>$now,'updated_at'=>$now,'version'=>1]);return $ok===false?self::error('database_error','Quality state could not be stored safely.',500):(int)$wpdb->insert_id;}
    private static function wipe_messages(array &$messages):void{foreach($messages as &$message)$message['body']='';unset($message);}
    private static function bucket(float|int $value,array $cuts):string{$i=0;foreach($cuts as $cut){if($value<$cut)return 'b'.$i;$i++;}return 'b'.$i;}
    private static function call_member(int $call,int $u):bool{global $wpdb;return(bool)$wpdb->get_var($wpdb->prepare("SELECT id FROM ".SN_DB::table('call_members')." WHERE call_id=%d AND user_id=%d AND status IN ('invited','joined') LIMIT 1",$call,$u));}
    private static function decode(object $row):array|WP_Error{$plain=SN_Communication_Crypto::decrypt((string)$row->payload_cipher,'future-record|'.(string)$row->feature_id.'|'.(int)$row->owner_id.'|'.(string)$row->scope_type.'|'.(int)$row->scope_id);if(is_wp_error($plain))return $plain;$data=json_decode($plain,true);return is_array($data)?$data:self::error('sn_future_record_invalid','Advanced communication data is invalid.',500);}
    private static function encode(object $row,array $data):string|WP_Error{return SN_Communication_Crypto::encrypt((string)wp_json_encode($data),'future-record|'.(string)$row->feature_id.'|'.(int)$row->owner_id.'|'.(string)$row->scope_type.'|'.(int)$row->scope_id);}
    private static function not_found():WP_Error{return self::error('not_found','Requested communication object is unavailable.',404);}private static function error(string $c,string $m,int $s):WP_Error{return new WP_Error($c,$m,['status'=>$s]);}
